#!/usr/bin/env bash
# Regenerates the public sample report committed at docs/demo/index.html.
#
# The report is the real thing: the CLI is run against validation/reactor, a fixture that
# deliberately trips several rules, and the HTML it writes is copied into the site. Keeping it
# reproducible means the demo cannot drift from what the tool actually produces.
#
# It is also the page a stranger is shown as proof of the product, so the version it stamps into
# itself ("Generated by AEM Code Analyser v...") has to be the released version the site publishes
# in docs/_data/version.yml. A demo stamped "1.0.11-SNAPSHOT" advertises a build nobody can
# download, so this script refuses to write one: it regenerates the demo only from a jar whose
# version matches version.yml, and the release workflow runs it with the jar it just built.
#
# Usage:
#   scripts/build-demo-report.sh [jar]    regenerate docs/demo/index.html from <jar>
#   scripts/build-demo-report.sh --check  verify the committed demo matches version.yml
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
VERSION_FILE="$ROOT/docs/_data/version.yml"
DEMO="$ROOT/docs/demo/index.html"

# The version the site publishes, e.g. "1.0.10".
site_version() {
  sed -n 's/^current:[[:space:]]*//p' "$VERSION_FILE" | head -n1 | tr -d "\"' \t"
}

# Every version the report stamps into itself, one per line and deduplicated.
stamped_versions() {
  grep -oE 'v[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z]+)*' "$1" \
    | sed 's/^v//' | sort -u
}

check() {
  local expected actual
  expected="$(site_version)"
  [ -n "$expected" ] || { echo "no 'current:' entry in $VERSION_FILE" >&2; exit 2; }
  [ -f "$DEMO" ] || { echo "missing $DEMO" >&2; exit 2; }
  actual="$(stamped_versions "$DEMO" | tr '\n' ' ' | sed 's/ $//')"
  if [ "$actual" != "$expected" ]; then
    echo "docs/demo/index.html is stamped with:  ${actual:-<no version found>}" >&2
    echo "docs/_data/version.yml publishes:      $expected" >&2
    echo "Regenerate the demo from the released CLI jar (see this script's header)." >&2
    exit 1
  fi
  echo "Demo version matches docs/_data/version.yml ($expected)."
}

if [ "${1:-}" = "--check" ]; then
  check
  exit 0
fi

JAR="${1:-$ROOT/aem-analyser-cli/target/aem-analyser-cli.jar}"
[ -f "$JAR" ] || { echo "jar not found: $JAR (run 'mvn -DskipTests package' first)" >&2; exit 2; }

expected="$(site_version)"
jar_version="$(java -jar "$JAR" --version 2>/dev/null | awk 'NF {print $NF}' | head -n1)"
if [ "$jar_version" != "$expected" ]; then
  echo "The demo is published as $expected (docs/_data/version.yml), but $JAR reports '$jar_version'." >&2
  echo "A SNAPSHOT build must never be stamped into the published demo." >&2
  echo "Regenerate it from the released jar instead, e.g.:" >&2
  echo "  gh release download v$expected -R RohithV16/aem-code-analyser -p aem-analyser-cli.jar" >&2
  echo "  scripts/build-demo-report.sh aem-analyser-cli.jar" >&2
  echo "The release workflow does this automatically with the jar it builds." >&2
  exit 3
fi

OUT="$(mktemp -d)"
trap 'rm -rf "$OUT"' EXIT

# The fixture has findings, so the gate exits 1 by design; the report is still written.
# The published page has a stable URL, so the report that goes there declares it as its canonical
# (and gains og:url) instead of shipping a page with no address.
(cd "$ROOT" && java -Daem.analyser.siteUrl="https://rohithv16.github.io/aem-code-analyser/demo/" \
  -jar "$JAR" validation/reactor --format HTML -o "$OUT" >/dev/null || true)

# The report prints an absolute project root. The demo is published, so keep the path relative to
# the clone (the way the docs describe the fixture) instead of shipping a machine-specific path.
generated="$OUT/aem-analyser-report.html"
sed "s|$ROOT/validation/reactor|validation/reactor|g" "$generated" > "$generated.tmp"
mv "$generated.tmp" "$generated"
if grep -q "$ROOT" "$generated"; then
  echo "the report still contains the local checkout path $ROOT" >&2
  exit 4
fi

mkdir -p "$ROOT/docs/demo"
cp "$generated" "$DEMO"
echo "Wrote docs/demo/index.html"
check
